#Determiner le nombre de mots d'une chaine sans espace superflu ni ponctuation

ch=str(input("< "))

def nombre_mots(ch):
    nb = 1
    for i in range (len(ch)-1) :
        if ch[i] == " " and ch[i+1] != " " :
            nb += 1
    return nb

print("le nombre de mots de la chaine est: ",nombre_mots(ch))

